<div class="page-heading"><div><span class="eyebrow">Help centre</span><h1>How can we help?</h1><p>Create a ticket for admission, document, payment or technical questions.</p></div></div><div class="support-layout"><section class="card"><h2>Create support ticket</h2><p>Give the team enough detail to understand your question.</p><form method="post" action="<?= url('student/support') ?>"><?= csrf_field() ?><div class="form-grid"><label class="full"><span>Subject *</span><input name="subject" value="<?= e(old('subject')) ?>" required><?= error('subject')?'<small class="field-error">'.e(error('subject')).'</small>':'' ?></label><label class="full"><span>Category *</span><select name="category" required><option value="admission">Admission</option><option value="documents">Documents</option><option value="payment">Payment</option><option value="technical">Technical issue</option><option value="other">Other</option></select></label><label class="full"><span>Message *</span><textarea name="message" rows="7" required><?= e(old('message')) ?></textarea><?= error('message')?'<small class="field-error">'.e(error('message')).'</small>':'' ?></label></div><button class="button button-primary">Create ticket →</button></form></section><aside class="support-side"><section class="card quick-help"><span class="eyebrow">Before you send</span><h3>Quick answers</h3><a href="<?= url('faq') ?>" target="_blank">Read frequently asked questions <span>→</span></a><a href="<?= url('admissions') ?>" target="_blank">Review the admission guide <span>→</span></a><a href="<?= url('student/application#documents') ?>">Check document status <span>→</span></a></section><section class="card contact-mini"><b>Admissions helpline</b><strong>+91 33 4000 2027</strong><small>Mon–Sat · 9:30–17:30 IST</small></section></aside></div><?php if($tickets):?><section class="card ticket-list"><div class="card-heading"><div><span class="eyebrow">Your history</span><h2>Support tickets</h2></div></div><?php foreach($tickets as $ticket):?><a href="<?= url('student/support/'.$ticket['id']) ?>"><article><span class="ticket-icon">#</span><div><b><?= e($ticket['subject']) ?></b><small><?= e($ticket['ticket_number']) ?> · <?= e(ucfirst($ticket['category'])) ?> · Updated <?= format_date($ticket['updated_at'],true) ?></small></div><span class="status-pill status-<?= e($ticket['status']) ?>"><?= e(ucwords(str_replace('_',' ',$ticket['status']))) ?></span></article></a><?php endforeach?></section><?php endif?>
